function ActivityMidFestivalShopLeftToggleTab:Refresh(productList, isLock)
    self._productList = productList
    self._curSelectIndex = isNull(self._curSelectIndex) and 1 or checkNumber(self._curSelectIndex)
    self._isLock = isLock
