local shopName = {
    [1] = localize("初级商店"),
    [2] = localize("中级商店"),
    [3] = localize("高级商店")
}

--region private
function ActivityMidFestivalShopLeftToggleTab:IsUnlockHelper(productList)
    for _, product in ipairs(checkTable(productList)) do
        if product.currentStock > 0 then
            return false
        end
    end
    return true
end

function ActivityMidFestivalShopLeftToggleTab:RefreshGridItemByIndex(gridView, index)
    local luaIndex = index + 1
    local cell = gridView:NewListViewItem("ToggleCellNode1")
    ---@type CommonTabToggleLeftCell
    local scr = CfUtils.GetLuaScr(cell, "Game.Behaviours.CommonTabToggleLeftCell")
    local preList = self._productList[luaIndex - 1]
    local isUnLock = self:IsUnlockHelper(preList)
    scr:FreshBaseUI({
        text = shopName[luaIndex],
        lock = not isUnLock
    })
    scr:FreshSelectStatus(luaIndex == checkNumber(self._curSelectIndex))
    if luaIndex == checkNumber(self._curSelectIndex) then
        local preName = shopName[luaIndex - 1]
        Events.Broadcast(Constants.EventNames.ActivityMidFestivalShopLeftToggleSelect, self._productList[luaIndex], isUnLock, preName)
    end
    scr:SetCallBack(function()
        self._curSelectIndex = luaIndex
        self:RefreshUI()
    end)
    return cell
end

function ActivityMidFestivalShopLeftToggleTab:RefreshUI()
    if not self.ListView.IsListViewInit then
        self.ListView:InitGridView(#self._productList, Bind(self, self.RefreshGridItemByIndex))
    else
        GameUtils.ReloadData(self.ListView, #self._productList)
    end
end
